
SELECT 'analytics.fact_order_items' AS source_table, 'customer_key -> dim_customer_dataco.customer_key' AS relationship, COUNT(*) AS orphan_rows FROM analytics.fact_order_items c LEFT JOIN analytics.dim_customer_dataco p ON c.customer_key = p.customer_key WHERE p.customer_key IS NULL UNION ALL SELECT 'analytics.fact_order_items', 'geography_key -> dim_geography.geography_key', COUNT(*) FROM analytics.fact_order_items c LEFT JOIN analytics.dim_geography p ON c.geography_key = p.geography_key WHERE p.geography_key IS NULL UNION ALL SELECT 'analytics.fact_order_items', 'order_date_key -> dim_date.date_key', COUNT(*) FROM analytics.fact_order_items c LEFT JOIN analytics.dim_date p ON c.order_date_key = p.date_key WHERE p.date_key IS NULL UNION ALL SELECT 'analytics.fact_order_items', 'product_key -> dim_product.product_key', COUNT(*) FROM analytics.fact_order_items c LEFT JOIN analytics.dim_product p ON c.product_key = p.product_key WHERE p.product_key IS NULL UNION ALL SELECT 'analytics.fact_order_items', 'shipping_date_key -> dim_date.date_key', COUNT(*) FROM analytics.fact_order_items c LEFT JOIN analytics.dim_date p ON c.shipping_date_key = p.date_key WHERE p.date_key IS NULL UNION ALL SELECT 'core.inventory_master', 'product_id -> products.product_id', COUNT(*) FROM core.inventory_master c LEFT JOIN core.products p ON c.product_id = p.product_id WHERE p.product_id IS NULL UNION ALL SELECT 'core.inventory_snapshots', 'inventory_id -> inventory_master.inventory_id', COUNT(*) FROM core.inventory_snapshots c LEFT JOIN core.inventory_master p ON c.inventory_id = p.inventory_id WHERE p.inventory_id IS NULL UNION ALL SELECT 'core.inventory_snapshots', 'product_id -> products.product_id', COUNT(*) FROM core.inventory_snapshots c LEFT JOIN core.products p ON c.product_id = p.product_id WHERE p.product_id IS NULL UNION ALL SELECT 'core.order_items', 'order_id -> orders.order_id', COUNT(*) FROM core.order_items c LEFT JOIN core.orders p ON c.order_id = p.order_id WHERE p.order_id IS NULL UNION ALL SELECT 'core.order_items', 'product_id -> products.product_id', COUNT(*) FROM core.order_items c LEFT JOIN core.products p ON c.product_id = p.product_id WHERE p.product_id IS NULL UNION ALL SELECT 'core.orders', 'customer_id -> customers_dataco.customer_id', COUNT(*) FROM core.orders c LEFT JOIN core.customers_dataco p ON c.customer_id = p.customer_id WHERE p.customer_id IS NULL UNION ALL SELECT 'core.product_suppliers', 'product_id -> products.product_id', COUNT(*) FROM core.product_suppliers c LEFT JOIN core.products p ON c.product_id = p.product_id WHERE p.product_id IS NULL UNION ALL SELECT 'core.product_suppliers', 'supplier_id -> suppliers.supplier_id', COUNT(*) FROM core.product_suppliers c LEFT JOIN core.suppliers p ON c.supplier_id = p.supplier_id WHERE p.supplier_id IS NULL UNION ALL SELECT 'core.supplier_performance', 'supplier_id -> suppliers.supplier_id', COUNT(*) FROM core.supplier_performance c LEFT JOIN core.suppliers p ON c.supplier_id = p.supplier_id WHERE p.supplier_id IS NULL ORDER BY source_table, relationship;
